const digits = input[1];

const map = {
  '0': '',
  '1': '',
  '2': '2',
  '3': '3',
  '4': '322',
  '5': '5',
  '6': '53',
  '7': '7',
  '8': '7222',
  '9': '7332'
};

let result = '';
