console.log([...result].sort((a, b) => b - a).join(''));

const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const digits = input[1];

const mapping = [
  '', '', '2', '3', '322',
  '5', '53', '7', '7222', '7332'
];

const result = [];

for (const digit of digits) {
  result.push(...mapping[Number(digit)]);
}

result.sort((a, b) => b.localeCompare(a));
console.log(result.join(''));

